(47,11,'Tickrate','The tickrate defines how fast the server will update each entity\'s location.','TICKRATE','22',1,1,'required|integer|max:100','2026-10-15 01:42:54','2026-10-15 01:57:47'),
(48,11,'Lua Refresh','0 = disable Lua refresh,\r\n1 = enable Lua refresh','LUA_REFRESH','0',1,1,'required|boolean','2026-10-15 01:42:54','2026-10-15 01:57:47'),
(49,12,'Maximum Users','Maximum concurrent users on the mumble server.','MAX_USERS','100',1,0,'required|numeric|digits_between:1,5','2026-10-15 01:42:54','2026-10-15 01:57:47'),
(50,13,'Server Version','The version of Teamspeak 3 to use when running the server.','TS_VERSION','latest',1,1,'required|string|max:6','2026-10-15 01:42:54','2026-10-15 01:57:47'),
(51,13,'File Transfer Port','The Teamspeak file transfer port','FILE_TRANSFER','30033',1,0,'required|integer|between:1025,65535','2026-10-15 01:42:54','2026-10-15 01:57:47'),
