(53,13,'Query Protocols','Comma separated list of protocols that can be used to connect to the ServerQuery | \r\nPossible values are raw, ssh and http | \r\nE.g.: raw,ssh,http','QUERY_PROTOCOLS_VAR','raw,http,ssh',1,1,'required|string|max:12','2026-10-15 01:42:54','2026-10-15 01:57:47'),
(54,13,'Query SSH Port','TCP Port opened for ServerQuery connections using SSH','QUERY_SSH','10022',1,0,'required|integer|between:1025,65535','2026-10-15 01:42:54','2026-10-15 01:57:47'),
(55,13,'Query HTTP Port','TCP Port opened for ServerQuery connections using http','QUERY_HTTP','10080',1,0,'required|integer|between:1025,65535','2026-10-15 01:42:54','2026-10-15 01:57:47'),
(56,13,'Server Query Admin Password','The password for the server query admin user.','SERVERADMIN_PASSWORD','',1,1,'nullable|string|max:32','2026-10-15 01:42:54','2026-10-15 01:57:47'),
(57,14,'Server Name','The name of your server in the public server list.','HOSTNAME','A Rust Server',1,1,'required|string|max:60','2026-10-15 01:42:54','2026-10-15 01:57:47'),
(58,14,'Modding Framework','The modding framework to be used: carbon, oxide, vanilla.\r\nDefaults to \"vanilla\" for a non-modded server installation.','FRAMEWORK','vanilla',1,1,'required|in:vanilla,oxide,carbon','2026-10-15 01:42:54','2026-10-15 01:57:47'),
(59,14,'Level','The world file for Rust to use.','LEVEL','Procedural Map',1,1,'required|string|max:20','2026-10-15 01:42:54','2026-10-15 01:57:47'),
(60,14,'Description','The description under your server title. Commonly used for rules & info. Use \\n for newlines.','DESCRIPTION','Powered by Pterodactyl',1,1,'required|string','2026-10-15 01:42:54','2026-10-15 01:57:47'),
(61,14,'URL','The URL for your server. This is what comes up when clicking the \"Visit Website\" button.','SERVER_URL','http://pterodactyl.io',1,1,'nullable|url','2026-10-15 01:42:54','2026-10-15 01:57:47'),
(62,14,'World Size','The world size for a procedural map.','WORLD_SIZE','3000',1,1,'required|integer','2026-10-15 01:42:54','2026-10-15 01:57:47'),
(63,14,'World Seed','The seed for a procedural map.','WORLD_SEED','',1,1,'nullable|string','2026-10-15 01:42:54','2026-10-15 01:57:47'),
(64,14,'Max Players','The maximum amount of players allowed in the server at once.','MAX_PLAYERS','40',1,1,'required|integer','2026-10-15 01:42:54','2026-10-15 01:57:47'),
(65,14,'Server Image','The header image for the top of your server listing.','SERVER_IMG','',1,1,'nullable|url','2026-10-15 01:42:54','2026-10-15 01:57:47'),
(66,14,'Query Port','Server Query Port. Can\'t be the same as Game\'s primary port.','QUERY_PORT','27017',1,0,'required|integer','2026-10-15 01:42:54','2026-10-15 01:57:47'),
(67,14,'RCON Port','Port for RCON connections.','RCON_PORT','28016',1,0,'required|integer','2026-10-15 01:42:54','2026-10-15 01:57:47'),
(68,14,'RCON Password','RCON access password.','RCON_PASS','',1,1,'required|regex:/^[\\w.-]*$/|max:64','2026-10-15 01:42:54','2026-10-15 01:57:47'),
(69,14,'Save Interval','Sets the server’s auto-save interval in seconds.','SAVEINTERVAL','60',1,1,'required|integer','2026-10-15 01:42:54','2026-10-15 01:57:47'),
(70,14,'Additional Arguments','Add additional startup parameters to the server.','ADDITIONAL_ARGS','',1,1,'nullable|string','2026-10-15 01:42:54','2026-10-15 01:57:47'),
(71,14,'App Port','Port for the Rust+ App. -1 to disable.','APP_PORT','28082',1,0,'required|integer','2026-10-15 01:42:54','2026-10-15 01:57:47'),
(72,14,'Server Logo','The circular server logo for the Rust+ app.','SERVER_LOGO','',1,1,'nullable|url','2026-10-15 01:42:54','2026-10-15 01:57:47'),
(73,14,'Custom Map URL','Overwrites the map with the one from the direct download URL. Invalid URLs will cause the server to crash.','MAP_URL','',1,1,'nullable|url','2026-10-15 01:42:54','2026-10-15 01:57:47'),
(74,15,'Git Repo Address','GitHub Repo to clone\n\nI.E. https://github.com/user_name/repo_name','GIT_ADDRESS','',1,1,'nullable|string','2026-10-15 01:45:26','2026-10-15 01:45:26'),
(75,15,'Install Branch','The branch to install.','BRANCH','',1,1,'nullable|string','2026-10-15 01:45:26','2026-10-15 01:45:26'),
(76,15,'Git Username','Username to auth with git.','USERNAME','',1,1,'nullable|string','2026-10-15 01:45:26','2026-10-15 01:45:26'),
(77,15,'Git Access Token','Password to use with git.\n\nIt\'s best practice to use a Personal Access Token.\nhttps://github.com/settings/tokens\nhttps://gitlab.com/-/profile/personal_access_tokens','ACCESS_TOKEN','',1,1,'nullable|string','2026-10-15 01:45:26','2026-10-15 01:45:26'),
(78,15,'Command Run','Command Start Bot','CMD_RUN','npm start',1,1,'required|string','2026-10-15 01:45:26','2026-10-15 01:45:26'),
(79,16,'Gunakan File Upload Manual?','Aktifkan saklar ini jika Anda mengupload file bot sendiri secara manual. Matikan saklar ini jika Anda ingin mendownload script otomatis dari GitHub. PENTING: Mode download dari GitHub HANYA akan terpicu jika Anda menekan tombol \"Reinstall Server\" di menu Settings (paling bawah).','USER_UPLOAD','1',1,1,'required|boolean','2026-10-15 01:45:26','2026-10-15 01:45:26'),
(80,16,'File Utama Script Python (Entry File)','Nama file utama yang bertugas menyalakan bot Anda. Contoh: main.py, app.py, atau bot.py','PY_FILE','main.py',1,1,'required|string','2026-10-15 01:45:26','2026-10-15 01:45:26'),
(81,16,'File Library / Requirements','Nama file yang berisi daftar library yang dibutuhkan script (standarnya requirements.txt). Server akan mendeteksi dan menginstalnya secara otomatis.','REQUIREMENTS_FILE','requirements.txt',1,1,'required|string','2026-10-15 01:45:26','2026-10-15 01:45:26'),
(82,16,'Link Repositori Git (Opsional)','Alamat link Repository GitHub (contoh: https://github.com/username/nama_repo). PENTING: Agar aksi Anda dalam mengisi/mengubah link Repository Github di kolom ini dapat terpicu, Anda WAJIB menekan tombol \"Reinstall Server\" di menu Settings (paling bawah) agar sistem mengunduhnya. Jika Anda tidak melakukannya, tidak akan ada yang terjadi, sistem tidak akan mengunduh file apapun dari repository github yang Anda tetapkan. Dan jika saklar File Upload Manual sedang aktif, input pada kolom ini akan diabaikan.','GIT_ADDRESS','',1,1,'nullable|string','2026-10-15 01:45:26','2026-10-15 01:45:26'),
(83,16,'Update Otomatis dari GitHub?','Aktifkan saklar ini agar bot otomatis menarik pembaruan (git pull) dari GitHub setiap kali server dinyalakan.','AUTO_UPDATE','0',1,1,'required|boolean','2026-10-15 01:45:26','2026-10-15 01:45:26'),
(84,16,'Cabang Git / Branch (Opsional)','Spesifik branch GitHub yang ingin diinstal. Kosongkan untuk menggunakan branch utama (main/master). PENTING: Perubahan di sini butuh klik \"Reinstall Server\" di menu Settings (paling bawah) agar berlaku.','BRANCH','',1,1,'nullable|string','2026-10-15 01:45:26','2026-10-15 01:45:26'),
(85,16,'Username GitHub (Private Repo)','Isi username GitHub Anda HANYA jika script yang didownload bersifat Repository Private. PENTING: Perubahan di sini butuh klik \"Reinstall Server\" di menu Settings (paling bawah) agar berlaku.','USERNAME','',1,1,'nullable|string','2026-10-15 01:45:26','2026-10-15 01:45:26'),
(86,16,'Token Akses GitHub (Private Repo)','Isi dengan Personal Access Token (PAT) HANYA jika repository Anda Private. PENTING: Perubahan di sini butuh klik \"Reinstall Server\" di menu Settings (paling bawah) agar berlaku.','ACCESS_TOKEN','',1,1,'nullable|string','2026-10-15 01:45:26','2026-10-15 01:45:26'),
(87,16,'Tambahan Module Python (Opsional)','Install paksa (pip install) modul Python tambahan yang tidak ada di file Requirements bawaan Anda. Pisahkan dengan spasi jika banyak (contoh: pyrogram flask requests).','PY_PACKAGES','',1,1,'nullable|string','2026-10-15 01:45:26','2026-10-15 01:45:26'),
(88,16,'Hapus Module Python (Opsional)','Hapus paksa modul tertentu. Pisahkan dengan spasi jika banyak.','UNPY_PACKAGES','',1,1,'nullable|string','2026-10-15 01:45:26','2026-10-15 01:45:26'),
(89,17,'[PRIORITAS 1] Mode Command Manual?','Jika mode ini NYALA (1), server akan MENGABAIKAN semua pengaturan otomatis di bawahnya (yang mengandung label \'PRIORITAS\'), dan murni menjalankan apa pun yang Anda ketik di kolom \'Command Manual\'. MATIKAN (0) mode ini jika Anda ingin sistem berjalan otomatis.','USE_MANUAL_COMMAND','0',1,1,'required|boolean','2026-10-15 01:45:26','2026-10-15 01:45:26'),
(90,17,'Command Manual (Khusus Mode Manual)','Hanya dieksekusi jika Mode Command Manual di atas NYALA (1). Contoh pengisian: \'npm install\', \'npm start\', \'node index.js\', dan sebagainya. Jika Mode Command Manual di atas dalam keadaan mati, maka kolom ini akan diabaikan.','MANUAL_COMMAND','npm install',1,1,'nullable|string','2026-10-15 01:45:26','2026-10-15 01:45:26'),
(91,17,'[PRIORITAS 2] Gunakan NPM Start Otomatis?','Hanya berfungsi jika Mode Command Manual MATI (0). Aktifkan mode ini agar server memprioritaskan eksekusi command start dari package.json (jika ada). Jika package.json tidak ada atau isinya tidak mengandung command eksekusi, server akan lanjut ke \'PRIORITAS 3\' secara otomatis. Matikan mode ini untuk memaksa server mengabaikan package.json dan murni menjalankan [File Utama] beserta [Argumen Node] yang Anda tentukan di bawah.','USE_NPM_START','1',1,1,'required|boolean','2026-10-15 01:45:26','2026-10-15 01:45:26'),
(92,17,'[PRIORITAS 3] File Utama Script (Entry File)','Hanya dieksekusi jika Mode Command Manual MATI (0) dan NPM Start Otomatis MATI (0) (atau package.json tidak valid). Isi dengan nama file utama bot Anda, contoh: index.js, app.ts, dan lain sebagainya. Jika Mode Command Manual NYALA (1) atau NPM Start Otomatis NYALA (1) dan package.json valid, input pada kolom ini akan diabaikan.','MAIN_FILE','index.js',1,1,'required|string|max:32','2026-10-15 01:45:26','2026-10-15 01:45:26'),
(93,17,'Argumen Node Tambahan (Opsional)','Argumen ekstra khusus untuk [PRIORITAS 3]. Logika di sistem: \"node [File_Utama] ...[Argumen_Tambahan]\". Contoh pengisian: \"--max-old-space-size=1024\" (mengatur batas RAM), \"<url> <time> <rate> <threads>\" (Eksekusi DD*S), atau lainnya (tanpa tanda kutip ya). Nanti hasilnya menjadi seperti ini, contoh: \"node index.js --max-old-space-size=1024\". Biarkan KOSONG jika Anda tidak paham atau tidak diperlukan.','NODE_ARGS','',1,1,'nullable|string|max:64','2026-10-15 01:45:26','2026-10-15 01:45:26'),
(94,17,'Gunakan File Upload Manual?','Aktifkan mode ini jika Anda mengupload file bot sendiri secara manual. Matikan mode ini jika Anda ingin mendownload script otomatis dari GitHub. PENTING: Mode download dari GitHub HANYA akan terpicu jika Anda telah mengisi kolom-kolom di bawah untuk kebutuhan mengunduh repository github, dan Anda harus menekan tombol \"Reinstall Server\" di menu Settings (paling bawah).','USER_UPLOAD','1',1,1,'required|boolean','2026-10-15 01:45:26','2026-10-15 01:45:26'),
(95,17,'Link Repositori Git (Opsional)','Alamat link Repository GitHub (contoh: https://github.com/username/nama_repo). PENTING: Agar aksi Anda dalam mengisi/mengubah link Repository Github di kolom ini dapat terpicu, Anda WAJIB menekan tombol \"Reinstall Server\" di menu Settings (paling bawah) agar sistem mengunduhnya. Jika Anda tidak melakukannya, tidak akan ada yang terjadi, sistem tidak akan mengunduh file apapun dari repository github yang Anda tetapkan. Dan juga jika mode File Upload Manual sedang aktif, input pada kolom ini akan diabaikan.','GIT_ADDRESS','',1,1,'nullable|string','2026-10-15 01:45:26','2026-10-15 01:45:26'),
(96,17,'Update Otomatis dari GitHub?','Aktifkan mode ini agar bot otomatis menarik pembaruan (git pull) dari GitHub setiap kali server dinyalakan.','AUTO_UPDATE','0',1,1,'required|boolean','2026-10-15 01:45:26','2026-10-15 01:45:26'),
(97,17,'Cabang Git / Branch (Opsional)','Spesifik branch GitHub yang ingin diinstal. Kosongkan untuk menggunakan branch utama (main/master). PENTING: Perubahan di sini butuh klik \"Reinstall Server\" di menu Settings (paling bawah) agar berlaku.','BRANCH','',1,1,'nullable|string','2026-10-15 01:45:26','2026-10-15 01:45:26'),
(98,17,'Username GitHub (Private Repo)','Isi username GitHub Anda HANYA jika script yang di-unduh bersifat Repository Private. PENTING: Perubahan di sini butuh klik \"Reinstall Server\" di menu Settings (paling bawah) agar berlaku.','USERNAME','',1,1,'nullable|string','2026-10-15 01:45:26','2026-10-15 01:45:26'),
(99,17,'Token Akses GitHub (Private Repo)','Isi dengan Personal Access Token (PAT) HANYA jika repository Anda Private. PENTING: Perubahan di sini butuh klik \"Reinstall Server\" di menu Settings (paling bawah) agar berlaku.','ACCESS_TOKEN','',1,1,'nullable|string','2026-10-15 01:45:26','2026-10-15 01:45:26'),
(100,17,'Tambahan Package NPM (Opsional)','Install paksa (npm install) modul tambahan yang tidak ada di file package.json bawaan Anda. Pisahkan dengan spasi jika banyak (contoh: axios moment ssh).','NODE_PACKAGES','',1,1,'nullable|string','2026-10-15 01:45:26','2026-10-15 01:45:26'),
(101,17,'Hapus Package NPM (Opsional)','Hapus paksa modul tertentu. Pisahkan dengan spasi jika banyak.','UNNODE_PACKAGES','',1,1,'nullable|string','2026-10-15 01:45:26','2026-10-15 01:45:26');
/*!40000 ALTER TABLE `egg_variables` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `eggs`
--

DROP TABLE IF EXISTS `eggs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `eggs` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `nest_id` int(10) unsigned NOT NULL,
  `author` varchar(191) NOT NULL,
  `name` varchar(191) NOT NULL,
  `description` text DEFAULT NULL,
  `features` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`features`)),
  `docker_images` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`docker_images`)),
  `file_denylist` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`file_denylist`)),
  `update_url` text DEFAULT NULL,
  `config_files` text DEFAULT NULL,
  `config_startup` text DEFAULT NULL,
  `config_logs` text DEFAULT NULL,
  `config_stop` varchar(191) DEFAULT NULL,
  `config_from` int(10) unsigned DEFAULT NULL,
  `startup` text DEFAULT NULL,
  `script_container` varchar(191) NOT NULL DEFAULT 'alpine:3.4',
  `copy_script_from` int(10) unsigned DEFAULT NULL,
  `script_entry` varchar(191) NOT NULL DEFAULT 'ash',
  `script_is_privileged` tinyint(1) NOT NULL DEFAULT 1,
  `script_install` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `force_outgoing_ip` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `service_options_uuid_unique` (`uuid`),
  KEY `service_options_nest_id_foreign` (`nest_id`),
  KEY `eggs_config_from_foreign` (`config_from`),
  KEY `eggs_copy_script_from_foreign` (`copy_script_from`),
  CONSTRAINT `eggs_config_from_foreign` FOREIGN KEY (`config_from`) REFERENCES `eggs` (`id`) ON DELETE SET NULL,
  CONSTRAINT `eggs_copy_script_from_foreign` FOREIGN KEY (`copy_script_from`) REFERENCES `eggs` (`id`) ON DELETE SET NULL,
  CONSTRAINT `service_options_nest_id_foreign` FOREIGN KEY (`nest_id`) REFERENCES `nests` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
