(12,'699d3915-36cc-4778-8112-174699f6870e',3,'support@pterodactyl.io','Mumble Server','Mumble is an open source, low-latency, high quality voice chat software primarily intended for use while gaming.',NULL,'{\"Mumble\":\"ghcr.io\\/parkervcp\\/yolks:voice_mumble\"}','[]',NULL,'{\r\n    \"murmur.ini\": {\r\n        \"parser\": \"ini\",\r\n        \"find\": {\r\n            \"database\": \"/home/container/murmur.sqlite\",\r\n            \"logfile\": \"/home/container/murmur.log\",\r\n            \"port\": \"{{server.build.default.port}}\",\r\n            \"host\": \"0.0.0.0\",\r\n            \"users\": \"{{server.build.env.MAX_USERS}}\"\r\n        }\r\n    }\r\n}','{\r\n    \"done\": \"Server listening on\"\r\n}','{}','^C',NULL,'mumble-server -fg -ini murmur.ini','ghcr.io/pterodactyl/installers:alpine',NULL,'ash',1,'#!/bin/ash\r\n\r\nif [ ! -d /mnt/server/ ]; then\r\n    mkdir /mnt/server/\r\nfi\r\n\r\ncd /mnt/server\r\n\r\nFILE=/mnt/server/murmur.ini\r\nif [ -f \"$FILE\" ]; then\r\n    echo \"Config file already exists.\"\r\nelse \r\n    echo \"Downloading the config file.\"\r\n    apk add --no-cache murmur\r\n    cp /etc/murmur.ini /mnt/server/murmur.ini\r\n    apk del murmur\r\nfi\r\necho \"done\"','2026-10-15 01:42:54','2026-10-15 01:42:54',0),
(13,'42cd6e09-5874-42b9-931e-1a1f9b26e499',3,'support@pterodactyl.io','Teamspeak3 Server','VoIP software designed with security in mind, featuring crystal clear voice quality, endless customization options, and scalabilty up to thousands of simultaneous users.',NULL,'{\"ghcr.io\\/pterodactyl\\/yolks:debian\":\"ghcr.io\\/pterodactyl\\/yolks:debian\"}','[]',NULL,'{}','{\r\n    \"done\": \"listening on 0.0.0.0:\"\r\n}','{\r\n    \"custom\": true,\r\n    \"location\": \"logs/ts3.log\"\r\n}','^C',NULL,'./ts3server default_voice_port={{SERVER_PORT}} query_port={{QUERY_PORT}} filetransfer_ip=0.0.0.0 filetransfer_port={{FILE_TRANSFER}} query_http_port={{QUERY_HTTP}} query_ssh_port={{QUERY_SSH}} query_protocols={{QUERY_PROTOCOLS_VAR}} serveradmin_password={{SERVERADMIN_PASSWORD}} license_accepted=1','ghcr.io/pterodactyl/installers:alpine',NULL,'ash',1,'#!/bin/ash\r\n# TS3 Installation Script\r\n#\r\n# Server Files: /mnt/server\r\n\r\nif [ -z ${TS_VERSION} ] || [ ${TS_VERSION} == latest ]; then\r\n    TS_VERSION=$(curl -sSL https://teamspeak.com/versions/server.json | jq -r \'.linux.x86_64.version\')\r\nfi\r\n\r\ncd /mnt/server\r\n\r\necho -e \"getting files from http://files.teamspeak-services.com/releases/server/${TS_VERSION}/teamspeak3-server_linux_amd64-${TS_VERSION}.tar.bz2\" \r\ncurl -L http://files.teamspeak-services.com/releases/server/${TS_VERSION}/teamspeak3-server_linux_amd64-${TS_VERSION}.tar.bz2 | tar -xvj --strip-components=1\r\ncp ./redist/libmariadb.so.2 ./','2026-10-15 01:42:54','2026-10-15 01:42:54',0),
(14,'6f18537c-c889-48a1-a4eb-6c06633a3ece',4,'support@pterodactyl.io','Rust','The only aim in Rust is to survive. To do this you will need to overcome struggles such as hunger, thirst and cold. Build a fire. Build a shelter. Kill animals for meat. Protect yourself from other players, and kill them for meat. Create alliances with other players and form a town. Do whatever it takes to survive.','[\"steam_disk_space\"]','{\"ghcr.io\\/pterodactyl\\/games:rust\":\"ghcr.io\\/pterodactyl\\/games:rust\"}','[]',NULL,'{}','{\r\n    \"done\": \"Server startup complete\"\r\n}','{}','quit',NULL,'./RustDedicated -batchmode +server.port {{SERVER_PORT}} +server.queryport {{QUERY_PORT}} +server.identity \"rust\" +rcon.port {{RCON_PORT}} +rcon.web true +server.hostname \\\"{{HOSTNAME}}\\\" +server.level \\\"{{LEVEL}}\\\" +server.description \\\"{{DESCRIPTION}}\\\" +server.url \\\"{{SERVER_URL}}\\\" +server.headerimage \\\"{{SERVER_IMG}}\\\" +server.logoimage \\\"{{SERVER_LOGO}}\\\" +server.maxplayers {{MAX_PLAYERS}} +rcon.password \\\"{{RCON_PASS}}\\\" +server.saveinterval {{SAVEINTERVAL}} +app.port {{APP_PORT}}  $( [ -z ${MAP_URL} ] && printf %s \"+server.worldsize \\\"{{WORLD_SIZE}}\\\" +server.seed \\\"{{WORLD_SEED}}\\\"\" || printf %s \"+server.levelurl {{MAP_URL}}\" ) {{ADDITIONAL_ARGS}}','ghcr.io/pterodactyl/installers:debian',NULL,'bash',1,'#!/bin/bash\r\n# steamcmd Base Installation Script\r\n#\r\n# Server Files: /mnt/server\r\n\r\nSRCDS_APPID=258550\r\n\r\n## just in case someone removed the defaults.\r\nif [ \"${STEAM_USER}\" == \"\" ]; then\r\n    echo -e \"steam user is not set.\\n\"\r\n    echo -e \"Using anonymous user.\\n\"\r\n    STEAM_USER=anonymous\r\n    STEAM_PASS=\"\"\r\n    STEAM_AUTH=\"\"\r\nelse\r\n    echo -e \"user set to ${STEAM_USER}\"\r\nfi\r\n\r\n## download and install steamcmd\r\ncd /tmp\r\nmkdir -p /mnt/server/steamcmd\r\ncurl -sSL -o steamcmd.tar.gz https://steamcdn-a.akamaihd.net/client/installer/steamcmd_linux.tar.gz\r\ntar -xzvf steamcmd.tar.gz -C /mnt/server/steamcmd\r\nmkdir -p /mnt/server/steamapps # Fix steamcmd disk write error when this folder is missing\r\ncd /mnt/server/steamcmd\r\n\r\n# SteamCMD fails otherwise for some reason, even running as root.\r\n# This is changed at the end of the install process anyways.\r\nchown -R root:root /mnt\r\nexport HOME=/mnt/server\r\n\r\n## install game using steamcmd\r\n./steamcmd.sh +force_install_dir /mnt/server +login ${STEAM_USER} ${STEAM_PASS} ${STEAM_AUTH} +app_update ${SRCDS_APPID} ${EXTRA_FLAGS} validate +quit ## other flags may be needed depending on install. looking at you cs 1.6\r\n\r\n## set up 32 bit libraries\r\nmkdir -p /mnt/server/.steam/sdk32\r\ncp -v linux32/steamclient.so ../.steam/sdk32/steamclient.so\r\n\r\n## set up 64 bit libraries\r\nmkdir -p /mnt/server/.steam/sdk64\r\ncp -v linux64/steamclient.so ../.steam/sdk64/steamclient.so','2026-10-15 01:42:54','2026-10-15 01:42:54',0),
(15,'1b6078ca-ee1f-4f54-9586-8477ccb493cd',5,'bangsano135@gmail.com','Node.js V1','Jangan Lupa Support Terus Sano Official Ya😊',NULL,'{\"Nodejs 20\":\"ghcr.io\\/parkervcp\\/yolks:nodejs_20\",\"Nodejs 24\":\"ghcr.io\\/parkervcp\\/yolks:nodejs_24\",\"Nodejs 23\":\"ghcr.io\\/parkervcp\\/yolks:nodejs_23\",\"Nodejs 22\":\"ghcr.io\\/parkervcp\\/yolks:nodejs_22\",\"Nodejs 21\":\"ghcr.io\\/parkervcp\\/yolks:nodejs_21\",\"Nodejs 19\":\"ghcr.io\\/parkervcp\\/yolks:nodejs_19\",\"Nodejs 18\":\"ghcr.io\\/parkervcp\\/yolks:nodejs_18\",\"Nodejs 17\":\"ghcr.io\\/parkervcp\\/yolks:nodejs_17\",\"Nodejs 16\":\"ghcr.io\\/parkervcp\\/yolks:nodejs_16\",\"Nodejs 15\":\"ghcr.io\\/parkervcp\\/yolks:nodejs_15\",\"Nodejs 14\":\"ghcr.io\\/parkervcp\\/yolks:nodejs_14\",\"Nodejs 13\":\"ghcr.io\\/parkervcp\\/yolks:nodejs_13\",\"Nodejs 12\":\"ghcr.io\\/parkervcp\\/yolks:nodejs_12\",\"Nodejs 11\":\"ghcr.io\\/parkervcp\\/yolks:nodejs_11\",\"Nodejs 10\":\"ghcr.io\\/parkervcp\\/yolks:nodejs_10\",\"Nodejs 9\":\"ghcr.io\\/parkervcp\\/yolks:nodejs_9\",\"Nodejs 8\":\"ghcr.io\\/parkervcp\\/yolks:nodejs_8\",\"Nodejs 7\":\"ghcr.io\\/parkervcp\\/yolks:nodejs_7\",\"Nodejs 6\":\"ghcr.io\\/parkervcp\\/yolks:nodejs_6\",\"Nodejs 5\":\"ghcr.io\\/parkervcp\\/yolks:nodejs_5\",\"Nodejs 4\":\"ghcr.io\\/parkervcp\\/yolks:nodejs_4\",\"Nodejs 3\":\"ghcr.io\\/parkervcp\\/yolks:nodejs_3\",\"Nodejs 2\":\"ghcr.io\\/parkervcp\\/yolks:nodejs_2\",\"Nodejs 1\":\"ghcr.io\\/parkervcp\\/yolks:nodejs_1\"}','[]',NULL,'{}','{\r\n    \"done\": \"running\"\r\n}','{}','^^C',NULL,'if [[ -d .git ]] && [[ {{AUTO_UPDATE}} == \"1\" ]]; then git pull; fi; if [[ ! -z ${NODE_PACKAGES} ]]; then /usr/local/bin/npm install ${NODE_PACKAGES}; fi; if [[ ! -z ${UNNODE_PACKAGES} ]]; then /usr/local/bin/npm uninstall ${UNNODE_PACKAGES}; fi; if [ -f /home/container/package.json ]; then /usr/local/bin/npm install; fi; if [[ ! -z ${CUSTOM_ENVIRONMENT_VARIABLES} ]]; then vars=$(echo ${CUSTOM_ENVIRONMENT_VARIABLES} | tr \";\" \"\\n\"); for line in $vars; do export $line; done fi; /usr/local/bin/${CMD_RUN};','node:14-buster-slim',NULL,'bash',1,'#!/bin/bash\n# NodeJS App Installation Script\n#\n# Server Files: /mnt/server\napt update\napt install -y git curl jq file unzip make gcc g++ python python-dev libtool\n\nmkdir -p /mnt/server\ncd /mnt/server\n\nif [ \"${USER_UPLOAD}\" == \"true\" ] || [ \"${USER_UPLOAD}\" == \"1\" ]; then\n    echo -e \"assuming user knows what they are doing have a good day.\"\n    exit 0\nfi\n\nif [[ ${GIT_ADDRESS} != *.git ]]; then\n    GIT_ADDRESS=${GIT_ADDRESS}.git\nfi\n\nif [ -z \"${USERNAME}\" ] && [ -z \"${ACCESS_TOKEN}\" ]; then\n    echo -e \"using anon api call\"\nelse\n    GIT_ADDRESS=\"https://${USERNAME}:${ACCESS_TOKEN}@$(echo -e ${GIT_ADDRESS} | cut -d/ -f3-)\"\nfi\n\nif [ \"$(ls -A /mnt/server)\" ]; then\n    echo -e \"/mnt/server directory is not empty.\"\n    if [ -d .git ]; then\n        echo -e \".git directory exists\"\n        if [ -f .git/config ]; then\n            echo -e \"loading info from git config\"\n            ORIGIN=$(git config --get remote.origin.url)\n        else\n            echo -e \"files found with no git config\"\n            echo -e \"closing out without touching things to not break anything\"\n            exit 10\n        fi\n    fi\n\n    if [ \"${ORIGIN}\" == \"${GIT_ADDRESS}\" ]; then\n        echo \"pulling latest from github\"\n        git pull\n    fi\nelse\n    echo -e \"/mnt/server is empty.\\ncloning files into repo\"\n    if [ -z ${BRANCH} ]; then\n        echo -e \"cloning default branch\"\n        git clone ${GIT_ADDRESS} .\n    else\n        echo -e \"cloning ${BRANCH}\'\"\n        git clone --single-branch --branch ${BRANCH} ${GIT_ADDRESS} .\n    fi\nfi\n\necho \"Installing nodejs packages\"\nif [[ ! -z ${NODE_PACKAGES} ]]; then\n    /usr/local/bin/npm install ${NODE_PACKAGES}\nfi\n\nif [ -f /mnt/server/package.json ]; then\n    /usr/local/bin/npm install --production\nfi\n\necho -e \"install complete\"\nexit 0','2026-10-15 01:45:26','2026-10-15 01:45:26',0),
(16,'916c47a6-d086-42bc-9472-16a2c2286e73',5,'bangsano135@gmail.com','Python','Environment Python cerdas yang dioptimalkan. Server akan menginstal library secara otomatis dari file requirements.txt dan merutekan eksekusi ke file utama tanpa konfigurasi manual yang rumit.',NULL,'{\"Python 3.13 (Eksperimental)\":\"ghcr.io\\/ptero-eggs\\/yolks:python_3.13\",\"Python 3.12 (Paling Stabil & Direkomendasikan)\":\"ghcr.io\\/ptero-eggs\\/yolks:python_3.12\",\"Python 3.11\":\"ghcr.io\\/ptero-eggs\\/yolks:python_3.11\",\"Python 3.10\":\"ghcr.io\\/ptero-eggs\\/yolks:python_3.10\",\"Python 3.9\":\"ghcr.io\\/ptero-eggs\\/yolks:python_3.9\",\"Python 3.8\":\"ghcr.io\\/ptero-eggs\\/yolks:python_3.8\"}','[]',NULL,'{}','{\r\n    \"done\": [\r\n        \"running\",\r\n        \"started\",\r\n        \"ready\",\r\n        \"listening\",\r\n        \"online\",\r\n        \"berhasil\",\r\n        \"sukses\",\r\n        \"success\",\r\n        \"siap\",\r\n        \"connected\"\r\n    ]\r\n}','{}','^C',NULL,'if [[ -d .git ]] && [[ \"{{AUTO_UPDATE}}\" == \"1\" ]]; then git pull; fi; if [[ ! -z \"${UNPY_PACKAGES}\" ]]; then pip uninstall -y ${UNPY_PACKAGES}; fi; if [[ ! -z \"${PY_PACKAGES}\" ]]; then pip install -U --prefix .local ${PY_PACKAGES}; fi; if [[ -f /home/container/${REQUIREMENTS_FILE} ]]; then pip install -U --prefix .local -r ${REQUIREMENTS_FILE}; fi; /usr/local/bin/python /home/container/${PY_FILE}','python:3.8-slim-bookworm',NULL,'bash',1,'#!/bin/bash\n# Script Instalasi App Python\n# Server Files: /mnt/server\napt update\napt install -y git curl jq file unzip make gcc g++ libtool\n\nmkdir -p /mnt/server\ncd /mnt/server\n\nif [ \"${USER_UPLOAD}\" == \"true\" ] || [ \"${USER_UPLOAD}\" == \"1\" ]; then\n    echo -e \"✅ Mode Upload File Manual terdeteksi. Melewati proses sinkronisasi GitHub...\"\n    exit 0\nfi\n\nif [ -z \"${GIT_ADDRESS}\" ]; then\n    echo -e \"\\n❌ ERROR FATAL: Anda memilih opsi Download dari GitHub (USER_UPLOAD = 0),\"\n    echo -e \"tetapi Link Repositori (GIT_ADDRESS) KOSONG!\"\n    echo -e \"Silakan isi Link GitHub di panel, atau ubah \'Gunakan File Upload Manual\' menjadi 1.\\n\"\n    exit 1\nfi\n\nif [ ! -z \"${USERNAME}\" ] || [ ! -z \"${ACCESS_TOKEN}\" ]; then\n    if [ -z \"${USERNAME}\" ] || [ -z \"${ACCESS_TOKEN}\" ]; then\n        echo -e \"\\n❌ ERROR FATAL: Kredensial Private Repo Tidak Lengkap!\"\n        echo -e \"Anda mengisi salah satu antara USERNAME atau ACCESS_TOKEN, tetapi mengosongkan yang lainnya.\"\n        echo -e \"Keduanya WAJIB diisi bersamaan jika repo berstatus Private, atau KOSONGKAN keduanya jika repo Public.\\n\"\n        exit 1\n    fi\nfi\n\nif [[ ${GIT_ADDRESS} != *.git ]]; then\n    GIT_ADDRESS=${GIT_ADDRESS}.git\nfi\n\nif [ -z \"${USERNAME}\" ] && [ -z \"${ACCESS_TOKEN}\" ]; then\n    echo -e \"Mencoba akses GitHub anonim (Tanpa Token)...\"\nelse\n    GIT_ADDRESS=\"https://${USERNAME}:${ACCESS_TOKEN}@$(echo -e ${GIT_ADDRESS} | cut -d/ -f3-)\"\nfi\n\nif [ \"$(ls -A /mnt/server)\" ]; then\n    echo -e \"⚠️ Peringatan: Direktori /mnt/server tidak kosong.\"\n    if [ -d .git ]; then\n        echo -e \"Direktori .git ditemukan.\"\n        if [ -f .git/config ]; then\n            echo -e \"Memuat informasi dari git config...\"\n            ORIGIN=$(git config --get remote.origin.url)\n        else\n            echo -e \"❌ File ditemukan tetapi tidak ada git config.\"\n            echo -e \"Membatalkan proses instalasi agar tidak merusak file Anda yang sudah ada.\"\n            exit 10\n        fi\n    fi\n\n    if [ \"${ORIGIN}\" == \"${GIT_ADDRESS}\" ]; then\n        echo \"🔄 Menarik pembaruan (pull) terbaru dari GitHub...\"\n        git pull\n    fi\nelse\n    echo -e \"Direktori kosong.\\n⬇️ Memulai kloning file dari repositori...\"\n    if [ -z \"${BRANCH}\" ]; then\n        echo -e \"Mengkloning cabang utama (default branch)...\"\n        git clone ${GIT_ADDRESS} .\n    else\n        echo -e \"Mengkloning cabang spesifik: ${BRANCH}...\"\n        git clone --single-branch --branch ${BRANCH} ${GIT_ADDRESS} .\n    fi\nfi\n\nexport HOME=/mnt/server\n\necho \"📦 Menyiapkan environment Python...\"\n\nif [[ ! -z \"${UNPY_PACKAGES}\" ]]; then\n    echo \"🗑️ Menghapus paksa modul pip yang tidak diinginkan...\"\n    pip uninstall -y ${UNPY_PACKAGES}\nfi\n\nif [[ ! -z \"${PY_PACKAGES}\" ]]; then\n    echo \"Menginstal modul pip tambahan...\"\n    pip install -U --prefix .local ${PY_PACKAGES}\nfi\n\nif [ -f /mnt/server/${REQUIREMENTS_FILE} ]; then\n    echo \"Membaca dan menginstal dependensi dari ${REQUIREMENTS_FILE}...\"\n    pip install -U --prefix .local -r ${REQUIREMENTS_FILE}\nelse\n    echo \"ℹ️ Tidak ditemukan file ${REQUIREMENTS_FILE}, melewati proses instalasi massal.\"\nfi\n\necho -e \"✅ Instalasi selesai dengan sukses!\"\nexit 0','2026-10-15 01:45:26','2026-10-15 01:45:26',0),
(17,'4c97169d-b3e7-4d70-a3ea-47bf98516478',5,'bangsano135@gmail.com','Node.js V2 (Auto)','Environment Node.js tingkat lanjut dengan hierarki eksekusi 3 Prioritas. Mendukung Override Command Manual untuk kontrol penuh pengguna, deteksi \'npm start\' otomatis dari package.json, dan fallback ke eksekusi file utama. Modul NPM dari package.json akan diunduh secara otomatis tanpa konfigurasi manual dari pengguna.',NULL,'{\"Nodejs 20 (LTS - Direkomendasikan)\":\"ghcr.io\\/ptero-eggs\\/yolks:nodejs_20\",\"Nodejs 25 (Eksperimental)\":\"ghcr.io\\/ptero-eggs\\/yolks:nodejs_25\",\"Nodejs 24\":\"ghcr.io\\/ptero-eggs\\/yolks:nodejs_24\",\"Nodejs 23\":\"ghcr.io\\/ptero-eggs\\/yolks:nodejs_23\",\"Nodejs 22\":\"ghcr.io\\/ptero-eggs\\/yolks:nodejs_22\",\"Nodejs 21\":\"ghcr.io\\/ptero-eggs\\/yolks:nodejs_21\",\"Nodejs 19\":\"ghcr.io\\/ptero-eggs\\/yolks:nodejs_19\",\"Nodejs 18\":\"ghcr.io\\/ptero-eggs\\/yolks:nodejs_18\",\"Nodejs 17\":\"ghcr.io\\/ptero-eggs\\/yolks:nodejs_17\",\"Nodejs 16\":\"ghcr.io\\/ptero-eggs\\/yolks:nodejs_16\",\"Nodejs 14\":\"ghcr.io\\/ptero-eggs\\/yolks:nodejs_14\",\"Nodejs 12\":\"ghcr.io\\/ptero-eggs\\/yolks:nodejs_12\"}','[]',NULL,'{}','{\r\n    \"done\": [\r\n        \"running\",\r\n        \"started\",\r\n        \"ready\",\r\n        \"listening\",\r\n        \"online\",\r\n        \"berhasil\",\r\n        \"sukses\",\r\n        \"success\",\r\n        \"siap\",\r\n        \"connected\"\r\n    ]\r\n}','{}','^C',NULL,'ESC=$(printf \'\\033\'); printf \"${ESC}c\"; echo -e \"\\n${ESC}[1;36m✨ Node.js Egg by Sano Official ✨${ESC}[0m\\n\"; if [[ -d .git ]] && [[ \"{{AUTO_UPDATE}}\" == \"1\" ]]; then git pull; fi; if [[ ! -z \"${UNNODE_PACKAGES}\" ]]; then npm uninstall ${UNNODE_PACKAGES}; fi; if [[ ! -z \"${NODE_PACKAGES}\" ]]; then npm install ${NODE_PACKAGES}; fi; if [ -f /home/container/package.json ]; then npm install; fi; if [[ \"{{USE_MANUAL_COMMAND}}\" == \"1\" ]]; then if [[ -z \"${MANUAL_COMMAND}\" ]]; then echo -e \"\\n${ESC}[0;31m[ERROR FATAL] Mode Command Manual AKTIF, tetapi kolom \'Command Manual\' KOSONG!${ESC}[0m\\n${ESC}[0;33mSilakan isi perintah yang ingin dijalankan terlebih dahulu, atau MATIKAN mode \'Gunakan Command Manual\'-nya.${ESC}[0m\\n\"; exit 1; else eval \"${MANUAL_COMMAND}\"; fi; else if [[ \"{{USE_NPM_START}}\" == \"1\" ]] && [ -f /home/container/package.json ] && node -e \"const p=require(\'/home/container/package.json\'); process.exit((p.scripts && p.scripts.start) ? 0 : 1);\" 2>/dev/null; then npm start; elif [[ \"${MAIN_FILE}\" == \"*.js\" ]]; then node \"/home/container/${MAIN_FILE}\" ${NODE_ARGS}; else ts-node --esm \"/home/container/${MAIN_FILE}\" ${NODE_ARGS}; fi; fi','node:20-trixie-slim',NULL,'bash',1,'#!/bin/bash\n# Script Instalasi App NodeJS\n# Server Files: /mnt/server\n\nexport DEBIAN_FRONTEND=noninteractive\nexport NEEDRESTART_MODE=a\nexport NEEDRESTART_SUSPEND=1\nexport DEBCONF_NONINTERACTIVE_SEEN=true\n\napt update --allow-releaseinfo-change -y\napt install -y git curl jq file unzip make gcc g++ python3 python3-dev python3-pip libtool\n\necho -e \"Memperbarui NPM ke versi terbaru. Mohon tunggu...\"\nnpm install npm@latest --location=global\n\nmkdir -p /mnt/server\ncd /mnt/server\n\nif [ \"${USER_UPLOAD}\" == \"true\" ] || [ \"${USER_UPLOAD}\" == \"1\" ]; then\n    echo -e \"✅ Mode Upload File Manual terdeteksi. Melewati proses sinkronisasi GitHub...\"\n    exit 0\nfi\n\nif [ -z \"${GIT_ADDRESS}\" ]; then\n    echo -e \"\\n❌ ERROR FATAL: Anda memilih opsi Download dari GitHub (USER_UPLOAD = 0),\"\n    echo -e \"tetapi Link Repositori (GIT_ADDRESS) KOSONG!\"\n    echo -e \"Silakan isi Link GitHub di panel, atau ubah \'Gunakan File Upload Manual\' menjadi 1.\\n\"\n    exit 1\nfi\n\nif [ ! -z \"${USERNAME}\" ] || [ ! -z \"${ACCESS_TOKEN}\" ]; then\n    if [ -z \"${USERNAME}\" ] || [ -z \"${ACCESS_TOKEN}\" ]; then\n        echo -e \"\\n❌ ERROR FATAL: Kredensial Private Repo Tidak Lengkap!\"\n        echo -e \"Anda mengisi salah satu antara USERNAME atau ACCESS_TOKEN, tetapi mengosongkan yang lainnya.\"\n        echo -e \"Keduanya WAJIB diisi bersamaan jika repo berstatus Private, atau KOSONGKAN keduanya jika repo Public.\\n\"\n        exit 1\n    fi\nfi\n\nif [[ ${GIT_ADDRESS} != *.git ]]; then\n    GIT_ADDRESS=${GIT_ADDRESS}.git\nfi\n\nif [ -z \"${USERNAME}\" ] && [ -z \"${ACCESS_TOKEN}\" ]; then\n    echo -e \"Mencoba akses GitHub anonim (Tanpa Token)...\"\nelse\n    GIT_ADDRESS=\"https://${USERNAME}:${ACCESS_TOKEN}@$(echo -e ${GIT_ADDRESS} | cut -d/ -f3-)\"\nfi\n\nif [ \"$(ls -A /mnt/server)\" ]; then\n    echo -e \"⚠️ Peringatan: Direktori /mnt/server tidak kosong.\"\n    if [ -d .git ]; then\n        echo -e \"Direktori .git ditemukan.\"\n        if [ -f .git/config ]; then\n            echo -e \"Memuat informasi dari git config...\"\n            ORIGIN=$(git config --get remote.origin.url)\n        else\n            echo -e \"❌ File ditemukan tetapi tidak ada git config.\"\n            echo -e \"Membatalkan proses instalasi agar tidak merusak file Anda yang sudah ada.\"\n            exit 10\n        fi\n    fi\n\n    if [ \"${ORIGIN}\" == \"${GIT_ADDRESS}\" ]; then\n        echo \"🔄 Menarik pembaruan (pull) terbaru dari GitHub...\"\n        git pull\n    fi\nelse\n    echo -e \"Direktori kosong.\\n⬇️ Memulai kloning file dari repositori...\"\n    if [ -z \"${BRANCH}\" ]; then\n        echo -e \"Mengkloning cabang utama (default branch)...\"\n        git clone ${GIT_ADDRESS} .\n    else\n        echo -e \"Mengkloning cabang spesifik: ${BRANCH}...\"\n        git clone --single-branch --branch ${BRANCH} ${GIT_ADDRESS} .\n    fi\nfi\n\necho \"📦 Menginstal library / packages Node.js...\"\nif [[ ! -z \"${NODE_PACKAGES}\" ]]; then\n    npm install ${NODE_PACKAGES}\nfi\n\nif [ -f /mnt/server/package.json ]; then\n    npm install --production\nfi\n\necho -e \"✅ Instalasi selesai dengan sukses!\"\nexit 0','2026-10-15 01:45:26','2026-10-15 01:45:26',0);
